Definition rs_ms (pc : Z) (rax : word) (sp : word) (gp tp t0 t1 t2 : word) (tot P : Z) (a0 a1 a2 a3 a4 a5 a6 a7 : word)
    (s5 s6 s7 s9 s10 s11 : word) (t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz tot) (wz (P + O_H_EC)) a0 a1 a2 a3 a4 a5 a6 a7
