Definition rs_frame (m : mem) (sp : word) (j8 : list byte) (t1c t2c : list cell) : Prop :=
  rw_cells rsegs m (bv_unsigned sp + -144) [CB 8 j8]
  /\ rw_cells rsegs m (bv_unsigned sp + -136) t1c /\ cells_size t1c = 24%nat
  /\ rw_cells rsegs m (bv_unsigned sp + -112) t2c /\ cells_size t2c = 24%nat.

