  rw_cells rsegs m (P + O_H_FB) (FlatBufCells FB) ->
  rw_cells rsegs m (P + O_H_EC) [CB 24 ej] ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 144 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 480 <= 2^64 ->
  0 <= fb_in FB -> fb_in FB <= fb_out FB -> fb_out FB < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (fun ms' => exists m' j8 jt1 jt2,
           munch [(lo, bv_unsigned sp); (P + O_H_EC, P + O_H_EC + 24)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
