        /\ rw_cells rsegs m' (bv_unsigned sp + -88) (map C8 (rs_sv s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra))
        /\ rw_cells rsegs m' (P + O_H_FB) (FlatBufCells FB)
        /\ rw_cells rsegs m' (P + O_H_EC) (ErrCodeCells EC_clear)
        /\ (   (fb_size FB = 0 /\ exists a0 a1 a2 a3,
                  ms' = rs_ms RS_DOREAD ra sp gp tp t0 t1 t2 0 P a0 a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s9 s10 s11 t3 t4 t5 t6 F fc m')
            \/ (0 < fb_size FB /\
                  ms' = rs_ms P_BP_PUT (wz RS_PUTRET) sp gp tp t0 t1 t2 0 P (wz P) (wz (fb_in FB)) (wz (fb_size FB)) (wz (P + O_H_EC)) a4 a5 a6 a7
