Definition rs_retd_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo tot : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6,
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz tot) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m (seg_rom rsegs)
      /\ stk rsegs m lo (bv_unsigned sp).

Definition rs_ret_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo P tot : Z) (j8 : list byte) (t1c t2c : list cell),
  rs_frame m sp j8 t1c t2c ->
  rw_cells rsegs m (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  stk rsegs m lo (bv_unsigned sp + -144) -> 0 <= lo -> lo <= bv_unsigned sp + -144 -> 0 <= tot < 2^64 ->
  evt rsegs (rs_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 F fc lo tot m)
    (rs_ms RS_RET rax sp gp tp t0 t1 t2 tot P a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x s10 s11 t3 t4 t5 t6 F fc m).

(* [comment removed for export] *)
Local Ltac blob2 H1 H2 :=
  let j1 := fresh "jb" in let j2 := fresh "jb" in let B1 := fresh "BL" in let B2 := fresh "BL" in
  destruct (rw_cells_forget _ _ _ _ H1) as [j1 B1]; destruct (rw_cells_forget _ _ _ _ H2) as [j2 B2]; clear H1 H2;
  cbn [cells_size csize Nat.add map] in B1, B2;
  lazymatch type of B1 with rw_cells _ _ ?a1 [CB ?n1 _] =>
    lazymatch type of B2 with rw_cells _ _ ?a2 _ =>
      replace a2 with (a1 + Z.of_nat n1) in B2 by lia;
      pose proof (rw_cells_CB_join rsegs _ _ _ _ _ _ B1 B2) as H1; clear B1 B2; cbn [Nat.add] in H1
    end end.

