(* [comment removed for export] *)
(* [comment removed for export] *)
Definition rs_W2 (lo : Z) (sp : word) (P : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -88); (P + O_H_FB, P + O_H_FB + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

(* [comment removed for export] *)
Definition rs_eqnm_post (ra sp gp tp s5x s6x s7x s9x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo P tot : Z) (FBC : list cell) (E1 : ecv) : machine_state -> Prop :=
  fun ms' => exists m',
          munch (rs_W2 lo sp P) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
       /\ rw_cells rsegs m' (P + O_H_FB) FBC
       /\ rw_cells rsegs m' (P + O_H_EC) (ErrCodeCells E1)
       /\ HttpCat m' true /\ XStatics m'
       /\ (   (is_needmore E1 = false /\ rs_retd_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 F fc lo tot m' ms')
           \/ (is_needmore E1 = true /\ exists j8' jt1 jt2 rax' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6',
                 stk rsegs m' lo (bv_unsigned sp + -144)
                 /\ rs_frame m' sp j8' [CB 24 jt1] [CB 24 jt2]
                 /\ rw_cells rsegs m' (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra))
                 /\ ms' = rs_ms RS_DOREAD rax' sp gp tp t0' t1' t2' tot P a0' a1' a2' a3' a4' a5' a6' a7' s5x s6x s7x s9x s10 s11 t3' t4' t5' t6' F fc m')).

Definition rs_eqnm_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (lo P tot : Z) (FBC : list cell) (E1 : ecv) (g : bool) (j8 jt2 : list byte) (t1c : list cell),
  rs_frame m sp j8 t1c [CB 24 jt2] ->
  rw_cells rsegs m (bv_unsigned sp + -88) (map C8 (rs_sv s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra)) ->
  rw_cells rsegs m (P + O_H_FB) FBC -> cells_size FBC = 48%nat ->
  rw_cells rsegs m (P + O_H_EC) (ErrCodeCells E1) -> ec_ok E1 -> (E1 = EC_clear \/ http_fail E1) ->
  HttpCat m g -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp + -144) -> lo + 176 <= bv_unsigned sp -> 0xb4000 <= lo ->
  bv_unsigned sp <= P -> P + 480 <= 2^64 -> 0 <= tot < 2^64 ->
  munch (rs_W2 lo sp P) m0 m -> wmono rsegs m0 m -> mem_inv rsegs m ->
  evt rsegs (rs_eqnm_post ra sp gp tp s5x s6x s7x s9x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v F fc m0 lo P tot FBC E1)
    (rs_ms 0x38d38 rax sp gp tp t0 t1 t2 tot P a0 a1 a2 a3 a4 a5 a6 a7 s5x s6x s7x s9x s10 s11 t3 t4 t5 t6 F fc m).
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

